const input = $('Execute Workflow Trigger').first().json;
const job = input.job;
const masterResume = input.masterResume;
const minScore = input.minMatchScore ?? 70;

const scorePrompt = `You are an expert technical recruiter. Score job fit using ONLY facts in the resume. Never invent skills. Return JSON only.

MASTER RESUME:
"""
${masterResume}
"""

JOB:
Title: ${job.title}
Company: ${job.company}
Location: ${job.location}
Description:
"""
${(job.description||'').slice(0,8000)}
"""

Return JSON: {"matchScore":0-100,"matchedSkills":[],"missingSkills":[],"matchedExperience":[],"locationFit":"saudi|remote|both|weak","summary":"","recommendation":"apply|review|skip"}`;

return [{ json: { ...input, scorePrompt, minScore } }];

const input = $('Execute Workflow Trigger').first().json;
const job = input.job;
const masterResume = input.masterResume;
const minScore = input.minMatchScore ?? 70;

let matchResult;
try {
  const ai = $('AI Match Score').first().json;
  matchResult = typeof ai.message?.content === 'string' ? JSON.parse(ai.message.content) : (ai.output || ai);
} catch (e) {
  matchResult = { matchScore: 0, summary: 'Scoring failed', recommendation: 'skip' };
}

const matchScore = Math.min(100, Math.max(0, Number(matchResult.matchScore) || 0));
const qualified = matchScore >= minScore;

return [{ json: { job, masterResume, matchResult: { ...matchResult, matchScore }, matchScore, qualified, minScore, autoApplyEnabled: input.autoApplyEnabled === true } }];

const ctx = $('Parse Match Score').first().json;
const resumeMd = $('AI Generate Resume').first().json.message?.content || '';
const coverText = $('AI Generate Cover Letter').first().json.message?.content || '';
const job = ctx.job;
const version = `v-${job.id.slice(0,8)}-${new Date().toISOString().slice(0,10)}`;

function mdToHtml(md) {
  return String(md).replace(/^### (.+)$/gm,'<h3>$1</h3>').replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^# (.+)$/gm,'<h1>$1</h1>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/^- (.+)$/gm,'<li>$1</li>').replace(/(<li>[\s\S]*?<\/li>)/g,'<ul>$1</ul>').replace(/\n\n/g,'</p><p>');
}

const resumeHtml = `<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><style>body{font-family:Arial;margin:40px;font-size:11pt;line-height:1.45}h1{font-size:22pt}h2{font-size:12pt;border-bottom:1px solid #333;margin-top:18px}</style></head><body>${mdToHtml(resumeMd)}</body></html>`;
const coverHtml = `<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><style>body{font-family:Arial;margin:40px;font-size:11pt;line-height:1.6}</style></head><body><p>${coverText.replace(/\n\n/g,'</p><p>')}</p></body></html>`;

return [{ json: {
  ...ctx,
  resumeMarkdown: resumeMd,
  coverLetterText: coverText,
  resumeHtml,
  coverHtml,
  resumeVersion: version,
  applicationStatus: ctx.autoApplyEnabled ? 'auto_apply_pending' : 'ready_for_review',
  processedAt: new Date().toISOString()
}}];

const ctx = $('Prepare PDF Payload').first().json;
return [{ json: {
  job: ctx.job,
  matchScore: ctx.matchScore,
  matchResult: ctx.matchResult,
  matchSummary: ctx.matchResult.summary,
  resumeVersion: ctx.resumeVersion,
  coverLetterText: ctx.coverLetterText,
  applicationStatus: ctx.applicationStatus,
  processedAt: ctx.processedAt,
  tier: 'qualified',
  hasPdf: true
}}];

const ctx = $input.first().json;
return [{ json: {
  job: ctx.job,
  matchScore: ctx.matchScore,
  matchResult: ctx.matchResult,
  matchSummary: ctx.matchResult.summary,
  applicationStatus: 'low_match',
  processedAt: new Date().toISOString(),
  tier: 'low_match',
  hasPdf: false
}}];

const ctx = $('Parse Match Score').first().json;
const job = ctx.job;
const masterResume = ctx.masterResume;
const mr = ctx.matchResult;

const resumePrompt = `Create an ATS resume in Markdown using ONLY facts from the master resume. Never invent skills or experience. Reorder for relevance to ${job.title} at ${job.company}. Mirror these matched keywords when truthful: ${(mr.matchedSkills||[]).join(', ')}.

MASTER RESUME:
${masterResume}

Return ONLY Markdown.`;

const coverPrompt = `Write a factual cover letter for ${job.title} at ${job.company}. Use ONLY resume facts. Never invent experience.

MASTER RESUME:
${masterResume}

MATCH: ${mr.summary}`;

return [{ json: { ...ctx, resumePrompt, coverPrompt } }];

const payload = $('Prepare PDF Payload').first().json;
const resumeBuffer = Buffer.from(payload.resumeHtml, 'utf-8');
const coverBuffer = Buffer.from(payload.coverHtml, 'utf-8');

return [
  {
    json: payload,
    binary: {
      resumeHtmlFile: {
        data: resumeBuffer.toString('base64'),
        mimeType: 'text/html',
        fileName: 'index.html'
      }
    }
  },
  {
    json: payload,
    binary: {
      coverHtmlFile: {
        data: coverBuffer.toString('base64'),
        mimeType: 'text/html',
        fileName: 'index.html'
      }
    }
  }
];
